#!/usr/bin/env bash
# regenerate-status.sh — STALE: docs/STATUS.md was removed in 2026-05-11 governance consolidation.
# Canonical maturity/status document is now .claude/knowledge-base/audits/2026-05-11/SUMMARY.md.
#
# This script previously updated auto-generated sections in docs/STATUS.md.
# It is retained for reference but will exit early if the target file does not exist.
#
# Per T4.4 of status-validation-and-doc-consolidation-plan.
#
# Preserves human-edited content. Only refreshes blocks between:
#   <!-- AUTO:START section-name -->
#   <!-- AUTO:END section-name -->
#
# Idempotent: running twice produces no diff if data unchanged.
#
# Sections regenerated:
#   activity-30d — `git log --since=30.days` summary
#   decay-summary — decay bucket counts
#
# Usage:
#   scripts/regenerate-status.sh                  # in-place update
#   scripts/regenerate-status.sh --check          # exit 1 if drift detected
#   scripts/regenerate-status.sh --dry-run        # print only

set -euo pipefail

STATUS_FILE="${STATUS_FILE:-docs/STATUS.md}"
CATALOG_FILE="${CATALOG_FILE:-docs/governance/claim-catalog.yaml}"
MODE="update"  # update | check | dry-run

while [[ $# -gt 0 ]]; do
    case "$1" in
        --check) MODE="check"; shift ;;
        --dry-run) MODE="dry-run"; shift ;;
        -h|--help)
            cat <<EOF
Usage: $(basename "$0") [--check | --dry-run]

Regenerate auto-sections in the status file (originally docs/STATUS.md, now removed).
  --check    Exit 1 if regeneration would change the file (drift detect)
  --dry-run  Print the changes without writing
EOF
            exit 0
            ;;
        *) echo "Unknown arg: $1" >&2; exit 1 ;;
    esac
done

if [[ ! -f "$STATUS_FILE" ]]; then
    echo "Status file not found at $STATUS_FILE (docs/STATUS.md was removed in 2026-05-11 governance consolidation)" >&2
    echo "Canonical maturity document is now .claude/knowledge-base/audits/2026-05-11/SUMMARY.md" >&2
    exit 0
fi

# Generate activity-30d section
gen_activity() {
    local since_iso
    since_iso="$(date -d '30 days ago' +%Y-%m-%d 2>/dev/null || date -v-30d +%Y-%m-%d 2>/dev/null || echo "30d-ago")"
    echo "_Auto-regenerated by infra/scripts/governance/regenerate-status.sh on $(date +%Y-%m-%d)_"
    echo ""
    echo "Recent commits (last 30 days):"
    echo ""
    echo '```'
    git log --since=30.days --oneline 2>/dev/null | head -20 || echo "(git not available)"
    echo '```'
}

# Generate decay-summary section
gen_decay() {
    if [[ ! -f "$CATALOG_FILE" ]]; then
        echo "_Catalog file not found at $CATALOG_FILE_"
        return
    fi
    echo "_Auto-regenerated by infra/scripts/governance/regenerate-status.sh on $(date +%Y-%m-%d)_"
    echo ""
    python3 - "$CATALOG_FILE" <<'PYEOF'
import sys
from datetime import date
import yaml

with open(sys.argv[1], 'r') as f:
    d = yaml.safe_load(f)

today = date.today()
fresh = aging = expiring = expired = 0

for c in d.get('claims', []):
    if 'expires' not in c or 'last_validated' not in c:
        continue
    try:
        exp_date = date.fromisoformat(str(c['expires']))
        lv_date = date.fromisoformat(str(c['last_validated']))
    except (ValueError, TypeError):
        continue

    ttl = c.get('ttl_days', 30)
    if isinstance(ttl, str):
        try:
            ttl = int(ttl)
        except ValueError:
            ttl = 30

    days_left = (exp_date - today).days
    if days_left < 0:
        expired += 1
    elif days_left < ttl * 0.2:
        expiring += 1
    elif days_left < ttl * 0.5:
        aging += 1
    else:
        fresh += 1

total = fresh + aging + expiring + expired
print(f"| Bucket | Count | % |")
print(f"|--------|------:|--:|")
print(f"| Fresh (>=50% TTL remaining) | {fresh} | {fresh*100//total if total else 0}% |")
print(f"| Aging (50%-80% TTL elapsed) | {aging} | {aging*100//total if total else 0}% |")
print(f"| Expiring (80%-100% TTL elapsed) | {expiring} | {expiring*100//total if total else 0}% |")
print(f"| **Expired (>=TTL elapsed)** | **{expired}** | **{expired*100//total if total else 0}%** |")
print(f"")
print(f"**Total claims:** {total}")
print(f"")
print(f"Run `task decay:scan` for full report by severity.")
PYEOF
}

# Replace block between markers
replace_block() {
    local section="$1"
    local content_file="$2"
    local target_file="$3"

    python3 - "$section" "$content_file" "$target_file" <<'PYEOF'
import sys
import re

section, content_file, target_file = sys.argv[1], sys.argv[2], sys.argv[3]

with open(content_file, 'r') as f:
    new_content = f.read().rstrip() + "\n"

with open(target_file, 'r') as f:
    target = f.read()

pattern = re.compile(
    rf'(<!-- AUTO:START {re.escape(section)} -->\n)(.*?)(<!-- AUTO:END {re.escape(section)} -->)',
    re.DOTALL
)
match = pattern.search(target)
if not match:
    print(f"WARN: no markers for section '{section}' in {target_file}", file=sys.stderr)
    sys.exit(0)

new_target = pattern.sub(
    lambda m: f"{m.group(1)}{new_content}{m.group(3)}",
    target
)

with open(target_file, 'w') as f:
    f.write(new_target)
PYEOF
}

ACTIVITY_TMP=$(mktemp)
DECAY_TMP=$(mktemp)
trap 'rm -f "$ACTIVITY_TMP" "$DECAY_TMP"' EXIT

gen_activity > "$ACTIVITY_TMP"
gen_decay > "$DECAY_TMP"

if [[ "$MODE" == "dry-run" ]]; then
    echo "=== activity-30d ==="
    cat "$ACTIVITY_TMP"
    echo ""
    echo "=== decay-summary ==="
    cat "$DECAY_TMP"
    exit 0
fi

if [[ "$MODE" == "check" ]]; then
    BACKUP=$(mktemp)
    cp "$STATUS_FILE" "$BACKUP"
    replace_block "activity-30d" "$ACTIVITY_TMP" "$STATUS_FILE"
    replace_block "decay-summary" "$DECAY_TMP" "$STATUS_FILE"
    if ! diff -q "$BACKUP" "$STATUS_FILE" > /dev/null; then
        echo "DRIFT detected — status file auto-sections need regeneration"
        diff "$BACKUP" "$STATUS_FILE" | head -50 || true
        cp "$BACKUP" "$STATUS_FILE"  # restore
        rm "$BACKUP"
        exit 1
    fi
    rm "$BACKUP"
    echo "OK — status file auto-sections current"
    exit 0
fi

# Default: update in place
replace_block "activity-30d" "$ACTIVITY_TMP" "$STATUS_FILE"
replace_block "decay-summary" "$DECAY_TMP" "$STATUS_FILE"
echo "Updated $STATUS_FILE auto-sections"
